using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using PocketCompendium.Features.BestiaryPages.Skills;
using PocketCompendium.Features.BestiaryPages.Model;
using Newtonsoft.Json;
using Xunit;

namespace PocketCompendium.Tests.BestiaryPages;

/// <summary>
/// Golden parity test: the C# <see cref="SkillEffectFormatter"/> must reproduce the
/// website's <c>formatSkillEffect</c> output for every exported skill. The corpus
/// (<c>Fixtures/skill-effect-parity.json</c>) is generated by
/// <c>pnpm --filter website gen:skill-effect-parity</c> and embedded into this assembly.
/// If this fails, fix the port or regenerate the corpus after an intentional
/// TypeScript change.
/// </summary>
public class SkillEffectFormatterTests
{
    internal sealed class ParityCase
    {
        public string skill_id { get; set; } = "";
        public string? monster_id { get; set; }
        public int? monster_level { get; set; }
        public int? runtime_level { get; set; }
        public MonsterDamageContext? monster { get; set; }
        public SkillDeliveryInput? delivery { get; set; }
        public SkillEffectInput input { get; set; } = new();
        public string expected { get; set; } = "";
    }

    internal static List<ParityCase> LoadCases()
    {
        var assembly = typeof(SkillEffectFormatterTests).Assembly;
        using var stream = assembly.GetManifestResourceStream("skill-effect-parity.json")
            ?? throw new InvalidOperationException(
                "skill-effect-parity.json not embedded; run `pnpm --filter website gen:skill-effect-parity`.");
        using var reader = new StreamReader(stream);
        var settings = new JsonSerializerSettings { Converters = { new LinearValueConverter() } };
        var cases = JsonConvert.DeserializeObject<List<ParityCase>>(reader.ReadToEnd(), settings)
            ?? throw new InvalidOperationException("parity corpus deserialized to null");
        foreach (var c in cases)
            c.input.monster = c.monster;
        return cases;
    }

    [Fact]
    public void FormatterMatchesWebsiteCorpus()
    {
        var cases = LoadCases();
        Assert.NotEmpty(cases);
        Assert.Contains(cases, c => c.monster_id == "nyxarion" && c.monster?.damage == 1620 && c.monster.magicDamage == 3150);
        Assert.Contains(cases, c => c.monster_id == null);

        var mismatches = new List<string>();
        foreach (var c in cases)
        {
            // The website groups thousands with U+202F. The mod draws text inside the game,
            // which shows English numbers with a comma, so the separator is the one
            // deliberate difference between the two.
            var expected = c.expected.Replace('\u202F', ',');
            var actual = SkillEffectFormatter.Format(c.input);
            if (actual != expected)
                mismatches.Add($"  {c.monster_id ?? "formula"}/{c.skill_id}: expected «{expected}» got «{actual}»");
        }

        Assert.True(
            mismatches.Count == 0,
            $"{mismatches.Count}/{cases.Count} skills diverged from the website formatter:\n"
                + string.Join("\n", mismatches.Take(40)));
    }

    [Fact]
    public void MonsterContextDropsTheReadersAttributeNotes()
    {
        var skill = LoadCases().Single(c => c.monster_id == null && c.skill_id == "venom_of_the_grave").input;
        Assert.NotEmpty(skill.notes);
        var notes = skill.notes.Values.ToArray();
        var formula = SkillEffectFormatter.Format(skill);
        skill.monster = new MonsterDamageContext();
        foreach (var note in notes)
        {
            Assert.Contains(note, formula);
            Assert.DoesNotContain(note, SkillEffectFormatter.Format(skill));
        }
    }

    [Fact]
    public void MonsterContextDescribesEnrageLikeTheWebsite()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "passive",
            is_enrage = true,
        };

        var formula = SkillEffectFormatter.Format(skill);
        skill.monster = new MonsterDamageContext();
        Assert.Equal(formula, SkillEffectFormatter.Format(skill));
    }

    [Fact]
    public void MonsterContextOmitsThreatThatOnlyPlayersRaise()
    {
        var skill = LoadCases().Single(c => c.monster_id == null && c.skill_id == "taunt").input;
        Assert.Contains("aggro", SkillEffectFormatter.Format(skill));
        skill.monster = new MonsterDamageContext();
        Assert.DoesNotContain("aggro", SkillEffectFormatter.Format(skill));
    }

    [Theory]
    [InlineData("dragon_claw_attack", "1,720 physical dmg, 5% stun (2s)")]
    [InlineData("dragon_ice_breath", "4,650 cold dmg, 75% stun (1.5s)")]
    [InlineData("fear", "100% fear (4s - 8s)")]
    public void NyxarionsSkillsShowResolvedDamageAndControl(string id, string expected)
    {
        var skill = LoadCases().Single(c => c.monster_id == "nyxarion" && c.skill_id == id).input;
        Assert.Equal(expected, SkillEffectFormatter.Format(skill));
    }

    [Fact]
    public void PercentageDamageScalesTheSumWithUnityFloatRounding()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "target_damage",
            damage_type = "Physical",
            damage = new LinearValue(101, 0),
            damage_percent = new LinearValue(0.5, 0),
            monster_damage_terms = new List<string> { "attack_power" },
            monster = new MonsterDamageContext { damage = 1620, magicDamage = 3150 },
        };
        Assert.Equal("860 physical dmg", SkillEffectFormatter.Format(skill));
        skill.damage_percent = new LinearValue(0.01, 0);
        skill.damage = new LinearValue(55, 0);
        Assert.Equal("17 physical dmg", SkillEffectFormatter.Format(skill));
    }

    [Fact]
    public void FrontalProjectilesIgnoreTheDamagePercentage()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "frontal_projectiles",
            damage_type = "Magic",
            damage = new LinearValue(100, 0),
            damage_percent = new LinearValue(0.5, 0),
            monster_damage_terms = new List<string> { "spell_power" },
            monster = new MonsterDamageContext { damage = 1620, magicDamage = 3150 },
        };
        Assert.Equal("3,250 magic dmg", SkillEffectFormatter.Format(skill));
    }

    [Fact]
    public void ZeroDamageControlDoesNotAddTheMonstersStats()
    {
        var skill = new SkillEffectInput
        {
            skill_type = "area_damage",
            damage_type = "Magic",
            damage = new LinearValue(0, 0),
            damage_percent = new LinearValue(0, 0),
            monster_damage_terms = new List<string> { "spell_power" },
            monster = new MonsterDamageContext { damage = 1620, magicDamage = 3150 },
            fear_chance = new LinearValue(1, 0),
            fear_time = new LinearValue(8, 0),
        };
        Assert.Equal("100% fear (4s - 8s)", SkillEffectFormatter.Format(skill));
        Assert.Null(MonsterDamage.Amount(skill));
    }
}
